def decode(buf):
    """Decode a percent-encoded byte string back to the original bytes.

    Partial percent sequences at either end (caused by truncation) are dropped.
    """
    out = bytearray()
    i = 0
    n = len(buf)
    while i < n:
        if buf[i] == ord('%'):
            if i + 3 > n:
                # Truncated escape at the end: drop it.
                break
            try:
                out.append(int(buf[i+1:i+3], 16))
            except ValueError:
                # Not a valid escape; keep the '%' literally.
                out.append(buf[i])
                i += 1
                continue
            i += 3
        else:
            out.append(buf[i])
            i += 1
    return bytes(out)

def encode_int(self, x):
    """Encode an integer using MessagePack format.

    Positive integers use fixint (0-127), uint8 (0xcc), uint16 (0xcd),
    uint32 (0xce), or uint64 (0xcf) formats.
    Negative integers use negative fixint (-32 to -1), int8 (0xd0),
    int16 (0xd1), int32 (0xd2), or int64 (0xd3) formats.
    """
    if 0 <= x <= 0x7f:
        self.buf.append(x)
    elif -32 <= x < 0:
        self.buf.append(0xe0 | (x + 32))
    elif 0 <= x <= 0xff:
        self.buf.append(0xcc)
        self.buf += struct.pack('>B', x)
    elif 0 <= x <= 0xffff:
